insert into public.topics(id,course_id,title,description,emoji,position,is_active) values ('b2-literature-cinema','b2-advanced','Литература и кино','Интерпретируем произведение, обсуждаем образность и пишем аргументированную рецензию','🎬',7,true) on conflict(id) do update set course_id=excluded.course_id,title=excluded.title,description=excluded.description,emoji=excluded.emoji,position=excluded.position,is_active=excluded.is_active;
