insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b2lit-grammar','Motyw zamkniętego okna można ___ jako znak izolacji.','["odczytać","przeczytał","odczytując się"]',0,'Można + infinitiv вводит допустимую интерпретацию, а не единственный ответ.',0),
('b2lit-grammar','Narratorka powiedziała: «Nie znam zakończenia». → Narratorka powiedziała, że ___ zakończenia.','["nie zna","nie znam","nie znała będzie"]',0,'При передаче реплики меняется лицо: znam → zna.',1),
('b2lit-grammar','Reżyser przywołuje obraz pustego peronu, ___ podkreślić samotność bohatera.','["aby","mimo że","natomiast"]',0,'Aby + infinitiv выражает цель художественного приёма.',2),
('b2lit-grammar','Finał jest niejednoznaczny; ___ widz może stworzyć własną interpretację.','["dzięki temu","pomimo","rzekomo że"]',0,'Dzięki temu связывает особенность финала с её эффектом.',3),
('b2lit-grammar','Составьте: Этот образ можно истолковать как символ утраченной близости.','["Ten obraz można odczytać jako symbol utraconej bliskości.","Ten obraz czyta jako utracił symbol bliskość.","Obrazem można odczytał utraconej bliskości symbol."]',0,'Można odczytać jako — готовая аналитическая рамка; symbol требует родительного определения.',4),
('b2lit-grammar','Составьте: Героиня сказала, что вернётся, но рассказчик ставит её слова под сомнение.','["Bohaterka powiedziała, że wróci, ale narrator poddaje jej słowa w wątpliwość.","Bohaterka mówiła wrócę, narrator wątpliwość jej słowami.","Powiedziała że wracała, lecz narrator poddawać słowa."]',0,'Косвенная речь использует że wróci; устойчивое сочетание — poddawać coś w wątpliwość.',5),
('b2lit-quiz','Co to jest fabuła?','["последовательность событий произведения","только мнение критика","список актёров"]',0,'Fabuła организует события истории.',0),
('b2lit-quiz','Które zdanie jest interpretacją, a nie streszczeniem?','["Pusty peron można odczytać jako znak samotności.","Bohater wysiada z pociągu.","Film trwa dziewięćdziesiąt minut."]',0,'Первая фраза объясняет возможный смысл образа.',1),
('b2lit-quiz','Krótki cytat w recenzji powinien…','["wspierać argument i zostać objaśniony","zastąpić całą analizę","pozostać bez kontekstu"]',0,'Цитата — доказательство, её функцию нужно объяснить.',2),
('b2lit-quiz','Co buduje napięcie w filmie?','["tempo, montaż i ograniczenie informacji","wyłącznie tytuł","lista źródeł"]',0,'Напряжение создаётся системой повествовательных и визуальных средств.',3),
('b2lit-quiz','Finał niejednoznaczny…','["dopuszcza kilka uzasadnionych odczytań","nie ma żadnego znaczenia","zawsze jest błędem autora"]',0,'Неоднозначность открывает несколько интерпретаций, если они опираются на текст.',4),
('b2lit-quiz','Film ___ do dawnej legendy miejskiej.','["odwołuje się","przywołuje się cytatem","symbolizuje do"]',0,'Odwoływać się do требует родительного падежа.',5),
('b2lit-quiz','Powiedział: «Nie wrócę». → Powiedział, że…','["nie wróci","nie wrócę","nie wracałem jutro"]',0,'В косвенной речи первое лицо меняется на третье.',6),
('b2lit-quiz','Co powinna zawierać przekonująca recenzja?','["tezę, przykłady i wyjaśnienie oceny","sam opis zakończenia","wyłącznie oceny liczbowe"]',0,'Аргументированная рецензия связывает оценку с конкретными средствами произведения.',7),
('b2lit-quiz','Warstwa wizualna oznacza…','["цвет, кадр, свет и композицию изображения","порядок глав книги","биографию зрителя"]',0,'Это система визуальных средств фильма.',8),
('b2lit-quiz','Która formuła sygnalizuje, że odczytanie nie jest jedyne?','["można interpretować jako","bez wątpienia oznacza tylko","autor udowodnił raz na zawsze"]',0,'Można interpretować jako оставляет место другим обоснованным прочтениям.',9),
('b2lit-reading-check','Dlaczego Ida wraca do miasta?','["Ma uporządkować mieszkanie po dziadku","Zaczyna pracę na stacji","Kręci film o pociągach"]',0,'Это её внешняя практическая задача.',0),
('b2lit-reading-check','Co może symbolizować światło na peronie?','["Oczekiwanie i szukanie kontaktu","Wyłącznie awarię techniczną","Sukces zawodowy Idy"]',0,'Рецензия связывает повторяющийся образ с ожиданием.',1),
('b2lit-reading-check','Jak film buduje napięcie?','["Przez krótkie rozmowy i urwane wiadomości","Przez ciągłe pościgi","Przez narrację dokumentalną"]',0,'Напряжение возникает из ограниченной информации.',2),
('b2lit-reading-check','Co zmienia ocenę milczenia siostry?','["Wiadomość, że także próbowała nawiązać kontakt","Nowa fotografia peronu","Decyzja o sprzedaży mieszkania"]',0,'Эта информация добавляет другую перспективу.',3),
('b2lit-reading-check','Dlaczego finał jest niejednoznaczny?','["Nie wiadomo, kto nadchodzi w ciemności","Ida nie przyjeżdża na peron","Film kończy się przed podróżą"]',0,'Звук шагов допускает разные прочтения.',4),
('b2lit-reading-check','Jak recenzent ostatecznie ocenia zakończenie?','["Jako spójne z obrazem i tematem pamięci","Jako przypadkowe i pozbawione sensu","Jako pełne rozwiązanie wszystkich wątków"]',0,'Финальный абзац обосновывает положительную оценку его связности.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2lit-recenzja-filmu-swiatlo-na-peronie','b2-literature-cinema','Recenzja filmu «Światło na peronie»','Оригинальная рецензия вымышленного фильма: образ, перспектива и неоднозначный финал','B2',13,'🎬','["Film «Światło na peronie» opowiada o Idzie, fotografce, która po latach wraca do rodzinnego miasta. Fabuła wydaje się prosta: bohaterka ma uporządkować mieszkanie po dziadku i szybko wyjechać. Reżyserka stopniowo ujawnia jednak, że prawdziwym celem podróży jest konfrontacja z pamięcią o nagłym rozstaniu z siostrą. Narrator pozostaje blisko punktu widzenia Idy, dlatego widz długo zna tylko jej wersję wydarzeń.","Najważniejszym motywem jest światło zapalające się co wieczór na nieczynnym peronie. Ida uważa je za przypadkową awarię, ale kamera wielokrotnie zatrzymuje się na pustej ławce pod lampą. Obraz można odczytać jako symbol oczekiwania: bohaterka twierdzi, że nie chce wracać do przeszłości, a jednocześnie stale szuka znaku od nieobecnej siostry. Chłodne kolory miasta kontrastują z ciepłym światłem peronu i wzmacniają ten sens.","Film skutecznie buduje napięcie, choć nie korzysta z gwałtownych zwrotów akcji. Zamiast nich pojawiają się krótkie rozmowy i urwane wiadomości. W jednej scenie Ida mówi: «Pamiętam tylko to, co pozwala mi odejść». Cytat nie wyjaśnia jej decyzji, lecz poddaje wiarygodność wspomnień w wątpliwość. Później siostra przekazuje przez znajomego, że również próbowała nawiązać kontakt. Ta informacja zmienia ocenę wcześniejszego milczenia.","Przemiana bohaterki jest przekonująca właśnie dlatego, że pozostaje niepełna. Ida zaczyna dostrzegać cudzy punkt widzenia, ale nie otrzymuje prostego pojednania. W finale czeka na peronie, gdy światło nagle gaśnie. Po chwili w ciemności słychać kroki, lecz film nie pokazuje, kto nadchodzi. Dla jednych będzie to zapowiedź spotkania, dla innych — znak, że bohaterka musi zaakceptować niepewność.","Niejednoznaczne zakończenie może rozczarować odbiorców oczekujących rozwiązania wszystkich wątków. Jest jednak spójne z warstwą wizualną i tematem zawodnej pamięci. «Światło na peronie» nie daje gotowej odpowiedzi, ale skłania do refleksji nad tym, ile naszych opowieści o bliskich powstaje bez poznania ich perspektywy."]','{"uporządkować":{"lemma":"uporządkować","translation":"привести в порядок","part_of_speech":"глагол"},"ujawnia":{"lemma":"ujawniać","translation":"раскрывает","part_of_speech":"глагол"},"rozstaniu":{"lemma":"rozstanie","translation":"расставании","part_of_speech":"существительное"},"wydarzeń":{"lemma":"wydarzenie","translation":"событий","part_of_speech":"существительное"},"nieczynnym":{"lemma":"nieczynny","translation":"неработающем","part_of_speech":"прилагательное"},"przypadkową":{"lemma":"przypadkowy","translation":"случайную","part_of_speech":"прилагательное"},"zatrzymuje":{"lemma":"zatrzymywać się","translation":"задерживается","part_of_speech":"глагол"},"oczekiwania":{"lemma":"oczekiwanie","translation":"ожидания","part_of_speech":"существительное"},"nieobecnej":{"lemma":"nieobecny","translation":"отсутствующей","part_of_speech":"прилагательное"},"wzmacniają":{"lemma":"wzmacniać","translation":"усиливают","part_of_speech":"глагол"},"gwałtownych":{"lemma":"gwałtowny","translation":"резких","part_of_speech":"прилагательное"},"urwane":{"lemma":"urwany","translation":"оборванные","part_of_speech":"прилагательное"},"wiarygodność":{"lemma":"wiarygodność","translation":"достоверность","part_of_speech":"существительное"},"nawiązać":{"lemma":"nawiązać","translation":"установить","part_of_speech":"глагол"},"przemiana":{"lemma":"przemiana","translation":"трансформация","part_of_speech":"существительное"},"pojednania":{"lemma":"pojednanie","translation":"примирения","part_of_speech":"существительное"},"nadchodzi":{"lemma":"nadchodzić","translation":"приближается","part_of_speech":"глагол"},"niepewność":{"lemma":"niepewność","translation":"неопределённость","part_of_speech":"существительное"},"rozczarować":{"lemma":"rozczarować","translation":"разочаровать","part_of_speech":"глагол"},"zawodnej":{"lemma":"zawodny","translation":"ненадёжной","part_of_speech":"прилагательное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2lit-reading-check"}',43,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
